import { OrderRepository } from '../../domain/order/OrderRepository';
import { parseOrderStatus } from '../../domain/order/OrderStatus';
import { OrderDto, toOrderDto } from '../dto/OrderDto';

export class ListOrdersByStateUseCase {
  constructor(private readonly orders: OrderRepository) {}

  execute(state: string): OrderDto[] {
    return this.orders.findByStatus(parseOrderStatus(state)).map(toOrderDto);
  }
}

